    {
        EnsureInitialized(); var status = Resolve<MIMEEntityGetTypeParamDelegate>("MIMEEntityGetTypeParam")(entity, symbol, out var rawHandle, out var length); if (status == ErrMimeNoData) return string.Empty; CheckStatus(status, "MIMEEntityGetTypeParam"); var handle = (nint)(nuint)rawHandle; if (handle == 0 || length == 0) { if (handle != 0) Resolve<OSMemFreeAccessDelegate>("OSMemFree")(handle); return string.Empty; }
        nint ptr = 0; try { ptr = Resolve<Search_OSLockObject>("OSLockObject")(handle); if (ptr == 0) throw new NotesException("Unable to lock MIME type parameter data."); var bytes = new byte[checked((int)length)]; Marshal.Copy(ptr, bytes, 0, bytes.Length); return Encoding.Latin1.GetString(bytes).TrimEnd('\0'); } finally { if (ptr != 0) Resolve<Search_OSUnlockObject>("OSUnlockObject")(handle); CheckStatus(Resolve<OSMemFreeAccessDelegate>("OSMemFree")(handle), "OSMemFree(MIMEEntityGetTypeParam)"); }
